window.ScripturaLexicons.BDAG_PART_0022 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alla-bdag\" data-source=\"BDAG\" data-search=\"ἀλλά alla mas porém contudo antes pelo contrário partícula adversativa contraste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλά</td><td>Partícula</td><td>mas; porém; antes; pelo contrário</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allage-bdag\" data-source=\"BDAG\" data-search=\"ἀλλαγή allage mudança alteração estações BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλαγή</td><td>Substantivo</td><td>mudança</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allasso-bdag\" data-source=\"BDAG\" data-search=\"ἀλλάσσω allasso mudar alterar trocar substituir transformar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλάσσω</td><td>Verbo</td><td>mudar; alterar; trocar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allachothen-bdag\" data-source=\"BDAG\" data-search=\"ἀλλαχόθεν allachothen de outro lugar João 10 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλαχόθεν</td><td>Advérbio</td><td>de outro lugar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allachou-bdag\" data-source=\"BDAG\" data-search=\"ἀλλαχοῦ allachou em outro lugar noutra direção Marcos 1 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλαχοῦ</td><td>Advérbio</td><td>em outro lugar; noutra direção</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allegoreo-bdag\" data-source=\"BDAG\" data-search=\"ἀλληγορέω allegoreo alegoricamente alegoria falar interpretar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλληγορέω</td><td>Verbo</td><td>falar alegoricamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hallelouia-bdag\" data-source=\"BDAG\" data-search=\"ἁλληλουϊά hallelouia aleluia louvai Yahweh fórmula litúrgica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλληλουϊά</td><td>Interjeição litúrgica</td><td>aleluia; louvai Yahweh</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allelon-bdag\" data-source=\"BDAG\" data-search=\"ἀλλήλων allelon uns aos outros reciprocamente pronome recíproco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλήλων</td><td>Pronome recíproco</td><td>uns aos outros; mutuamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allogenes-bdag\" data-source=\"BDAG\" data-search=\"ἀλλογενής allogenes estrangeiro samaritano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλογενής</td><td>Adjetivo</td><td>estrangeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alloioo-bdag\" data-source=\"BDAG\" data-search=\"ἀλλοιόω alloioo mudar alterar tornar diferente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλοιόω</td><td>Verbo</td><td>mudar; tornar diferente</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-alla-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλά</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦allá⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Homero+; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>; Schwyzer II 578.) Partícula geralmente adversativa (originariamente neutro plural de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>, “de outro modo”), indicando diferença ou contraste com o que precede, tanto no caso de orações individuais como de sentenças inteiras.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Depois de uma negativa ou depois de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέν\" data-meanings=\"de um lado; certamente\">μέν</span>: pelo contrário, mas, contudo, antes.</strong> <strong>a.</strong> Introduzindo contraste: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἦλθον καταλῦσαι, ἀλλὰ πληρῶσαι\" data-meanings=\"não vim abolir, mas cumprir\">οὐκ ἦλθον καταλῦσαι, ἀλλὰ πληρῶσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.17</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ πᾶς ὁ λέγων … ἀλλ’ ὁ ποιῶν\" data-meanings=\"não todo aquele que diz … mas aquele que faz\">οὐ πᾶς ὁ λέγων … ἀλλ’ ὁ ποιῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">7.21</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἀπέθανεν, ἀλλὰ καθεύδει\" data-meanings=\"não morreu, mas dorme\">οὐκ ἀπέθανεν, ἀλλὰ καθεύδει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.39</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκέτι οὐδένα εἶδον, ἀλλὰ τὸν Ἰησοῦν μόνον\" data-meanings=\"não viram mais ninguém, mas somente Jesus\">οὐκέτι οὐδένα εἶδον, ἀλλὰ τὸν Ἰησοῦν μόνον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">9.8</a> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ μὴ τὸν Ἰησοῦν\" data-meanings=\"senão Jesus\">εἰ μὴ τ. Ἰ.</span>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ … σαρκὶ ἀλλὰ μόνῳ πνεύματι\" data-meanings=\"não … pela carne, mas somente pelo espírito\">οὐ … σαρκὶ ἀλλὰ μόνῳ πνεύματι</span>, AcPl Ant 13 (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μόνον\" data-meanings=\"somente\">μόνον</span>, Aa I 237, 3). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἔστι θεὸς νεκρῶν ἀλλὰ ζώντων\" data-meanings=\"não é Deus de mortos, mas de vivos\">οὐκ ἔστι θεὸς νεκρῶν ἀλλὰ ζώντων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.38</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ καθῶς γέγραπται\" data-meanings=\"mas, conforme está escrito\">ἀλλὰ καθῶς γέγραπται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.21</a>, introduz uma declaração acerca de um procedimento que contrasta com o que precede.</p>\n<p class=\"entry-text\">Com força ascendente (B-D-F §448; Rob. 1187): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μόνον … ἀλλὰ καί\" data-meanings=\"não somente … mas também\">οὐ μόνον … ἀλλὰ καί</span>, <strong>não somente … mas também</strong> (frequente em EpArist; TestJob 47:2s.; Jos., <em>Bell.</em> 3, 102; Just., <em>A I</em> 5, 4): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μόνον δεθῆναι, ἀλλὰ καὶ ἀποθανεῖν\" data-meanings=\"não somente ser preso, mas também morrer\">οὐ μόνον δεθῆναι, ἀλλὰ καὶ ἀποθανεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μόνον σὲ ἀλλὰ καὶ πάντας τοὺς ἀκούοντας\" data-meanings=\"não somente tu, mas também todos os que ouvem\">οὐ μόνον σὲ ἀλλὰ καὶ πάντας τοὺς ἀκούοντας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">26.29</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">27.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">4.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">9.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">13.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">9.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.18</a>. Com o primeiro membro abreviado (compare TestJob 35:1), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μόνον δέ, ἀλλὰ καί\" data-meanings=\"não somente isto, mas também\">οὐ μόνον δέ, ἀλλὰ καί</span>, <strong>não somente isto, mas também</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ μόνον δέ … ἀλλὰ καὶ καυχώμεθα ἐν ταῖς θλίψεσιν\" data-meanings=\"não somente isso … mas também nos gloriamos nas tribulações\">οὐ μόνον δέ</span> (subentenda-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καυχώμεθα ἐπὶ τούτῳ\" data-meanings=\"gloriamo-nos nisso\">καυχώμεθα ἐπὶ τούτῳ</span>), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ καὶ καυχώμεθα ἐν ταῖς θλίψεσιν\" data-meanings=\"mas também nos gloriamos nas tribulações\">ἀλλὰ καὶ καυχώμεθα ἐν ταῖς θλίψεσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.3</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">8.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">9.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.19</a>.</p>\n<p class=\"entry-text\">Introduz o ponto principal depois de uma pergunta explícita ou implícita que recebeu resposta negativa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐχί, ἀλλὰ κληθήσεται Ἰωάννης\" data-meanings=\"não; antes, será chamado João\">οὐχί, ἀλλὰ κληθήσεται Ἰωάννης</span>, <strong>não; antes, será chamado João</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.60</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐχί, λέγω ὑμῖν, ἀλλὰ ἐὰν μὴ μετανοῆτε\" data-meanings=\"não! digo-vos; antes, se não vos arrependerdes\">οὐχί, λέγω ὑμῖν, ἀλλὰ ἐὰν μὴ μετανοῆτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">13.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">16.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.27</a> (TestAbr A 5 p. 82, 5; 31s. [Stone p. 12]; JosAs 4:15 e outros; ApcMos 6); depois de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μὴ γένοιτο\" data-meanings=\"de modo nenhum!\">μὴ γένοιτο</span>, que serve como forte negação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">3.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">7.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.21</a>. A resposta negativa pode ser omitida por ser óbvia: <strong>(não,) antes disso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.6</a> (como declaração).</p>\n<p class=\"entry-text\">Em lugar de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"mas; antes\">ἀ.</span>, encontra-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ ἤ\" data-meanings=\"senão; exceto\">ἀλλ’ ἤ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.51</a>; B 2:8. Também depois de negativa e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>, como em Platão, Xenofonte e outros (Kühner-G. II 284s.; IG IV, 951, 76 [320 a.C.]; PPetr II, 46a, 5 [200 a.C.]; Just., <em>A II</em> 4, 2 e outros; em pergunta retórica, PsSol 5:12; B-D-F §448, 8), significa <strong>exceto</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ γὰρ ἄλλα γράφομεν ὑμῖν ἀλλ’ ἢ ἃ ἀναγινώσκετε\" data-meanings=\"pois não vos escrevemos nada além do que podeis compreender\">οὐ γὰρ ἄλλα γράφομεν ὑμῖν ἀλλ’ ἢ ἃ ἀναγινώσκετε</span>, <strong>pois não vos escrevemos nada (além) do que podeis compreender</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.13</a>. Esta construção <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἄλλος ἀλλ’ ἤ\" data-meanings=\"nenhum outro senão\">οὐκ ἄλλος ἀλλ’ ἤ</span> combina <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἄλλος … ἀλλά\" data-meanings=\"não outro … mas\">οὐκ ἄλλος …, ἀλλά</span> (PTebt 104, 19 [92 a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μὴ ἐξέστω Φιλίσκωνι γυναῖκα ἄλλην ἐπαγαγέσθαι, ἀλλὰ Ἀπολλωνίαν\" data-meanings=\"não seja permitido a Filisco tomar outra mulher, mas Apolônia\">μὴ ἐξέστω Φιλίσκωνι γυναῖκα ἄλλην ἐπαγαγέσθαι, ἀλλὰ Ἀπολλωνίαν</span>), 1 Cl 51:5, e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἄλλος ἤ\" data-meanings=\"nenhum outro senão\">οὐκ ἄλλος ἤ …</span> (Ps.-Clem., <em>Hom.</em> 16, 20).</p>\n<p class=\"entry-text\"><strong>b.</strong> Dentro da mesma oração, contrastando palavras isoladas (Just., <em>A I</em> 15, 7 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ τούς δικαίους … ἀλλὰ τούς ἀσεβεῖς\" data-meanings=\"não os justos … mas os ímpios\">οὐ τούς δικαίους … ἀλλὰ τούς ἀσεβεῖς</span>, <em>D.</em> 48, 1): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ … δικαίους ἀλλ’ ἁμαρτωλούς\" data-meanings=\"não … justos, mas pecadores\">οὐ … δικαίους ἀλλ’ ἁμαρτωλούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.32</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἐμὲ δέχεται ἀλλὰ τὸν ἀποστείλαντά με\" data-meanings=\"não recebe a mim, mas aquele que me enviou\">οὐκ ἐμὲ δέχεται ἀλλὰ τὸν ἀποστείλαντά με</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.37</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ οὐ τί ἐγὼ θέλω ἀλλὰ τί σύ\" data-meanings=\"mas não o que eu quero, e sim o que tu queres\">ἀλλ’ οὐ τί ἐγὼ θέλω ἀλλὰ τί σύ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">14.36</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">6.38</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἐμὴ διδαχὴ οὐκ ἔστιν ἐμὴ ἀλλὰ τοῦ πέμψαντός με\" data-meanings=\"meu ensino não é meu, mas daquele que me enviou\">ἡ ἐμὴ διδαχὴ οὐκ ἔστιν ἐμὴ ἀλλὰ τοῦ πέμψαντός με</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">7.16</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἐγὼ ἀλλὰ ὁ κύριος\" data-meanings=\"não eu, mas o Senhor\">οὐκ ἐγὼ ἀλλὰ ὁ κύριος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.10</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ τῇ πορνείᾳ, ἀλλὰ τῷ κυρίῳ\" data-meanings=\"não para a prostituição, mas para o Senhor\">οὐ τῇ πορνείᾳ, ἀλλὰ τῷ κυρίῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">6.13</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ εἰς τὸ κρεῖσσον ἀλλὰ εἰς τὸ ἧσσον\" data-meanings=\"não para melhor, mas para pior\">οὐκ εἰς τὸ κρεῖσσον ἀλλὰ εἰς τὸ ἧσσον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">11.17</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἔστιν ἓν μέλος ἀλλὰ πολλά\" data-meanings=\"não é um só membro, mas muitos\">οὐκ ἔστιν ἓν μέλος ἀλλὰ πολλά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">12.14</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ εἰς τὸ ἀγαθὸν ἀλλ’ εἰς τὸ πονηρόν\" data-meanings=\"não para o bem, mas para o mal\">οὐκ εἰς τὸ ἀγαθὸν ἀλλ’ εἰς τὸ πονηρόν</span>, D 5:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐχ ὡς διδάσκαλος ἀλλ’ ὡς εἷς ἐξ ὑμῶν\" data-meanings=\"não como mestre, mas como um de vós\">οὐχ ὡς διδάσκαλος ἀλλ’ ὡς εἷς ἐξ ὑμῶν</span>, B 1:8, e outros.</p>\n<p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.23</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἔστιν ἐμὸν τοῦτο δοῦναι, ἀλλ’ οἷς ἡτοίμασται ὑπὸ τοῦ πατρός μου\" data-meanings=\"não me pertence conceder isso, mas [pertence] àqueles para quem foi preparado por meu Pai\">οὐκ ἔστιν ἐμὸν τοῦτο δοῦναι, ἀλλ’ οἷς ἡτοίμασται ὑπὸ τοῦ πατρός μου</span> foi abreviado de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἐμὸν … ἀλλὰ τοῦ πατρός, ὅς δώσει οἷς ἡτοίμασται ὑπ’ αὐτοῦ\" data-meanings=\"não é meu … mas do Pai, que dará àqueles para quem foi preparado por ele\">οὐκ ἐμὸν … ἀλλὰ τοῦ πατρός, ὅς δώσει οἷς ἡτοίμασται ὑπ’ αὐτοῦ</span>. Mas veja W. Beck, CTM 21, 1950, 606–610, para o sentido <strong>exceto</strong> em Mt 20.23 = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.40</a>, e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.22</a>, também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">9.8</a> v.l. (por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ μή\" data-meanings=\"senão; exceto\">εἰ μή</span>); D 9:5. Assim também B-D-F §448, 8; Mlt-Turner 330; M. Black, <em>An Aramaic Approach</em><sup>3</sup>, 1967, 113s.</p>\n<p class=\"entry-text\">Depois de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέν\" data-meanings=\"de um lado; certamente\">μέν</span>, indica que se seguirá uma frase limitadora: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάντα μὲν καθαρά, ἀλλὰ κακὸν τῷ ἀνθρώπῳ\" data-meanings=\"todas as coisas são de fato puras, mas é mau para o homem\">πάντα μὲν καθαρά, ἀλλὰ κακὸν τῷ ἀνθρώπῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14.20</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σὺ μὲν γὰρ καλῶς εὐχαριστεῖς, ἀλλ’ ὁ ἕτερος οὐκ οἰκοδομεῖται\" data-meanings=\"tu, de fato, dás graças bem, mas o outro não é edificado\">σὺ μὲν γὰρ καλῶς εὐχαριστεῖς, ἀλλ’ ὁ ἕτερος οὐκ οἰκοδομεῖται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.17</a>.</p>\n<p class=\"entry-text\">É digno de nota o uso de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"mas; antes\">ἀλλά</span> na literatura joanina, pois os membros contrastados nem sempre têm a mesma posição gramatical: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἦν ἐκεῖνος τὸ φῶς ἀλλ’ ἵνα μαρτυρήσῃ περὶ τοῦ φωτός\" data-meanings=\"ele não era a luz, mas [veio] para dar testemunho da luz\">οὐκ ἦν ἐκεῖνος τὸ φῶς ἀλλ’ ἵνα μαρτυρήσῃ περὶ τοῦ φωτός</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ μαρτυρῶν περὶ τοῦ φωτός\" data-meanings=\"mas dando testemunho acerca da luz\">ἀλλὰ μαρτυρῶν π. τ. φ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ᾔδειν αὐτόν ἀλλ’ … ἦλθον\" data-meanings=\"embora eu não o conhecesse, contudo vim\">οὐκ ᾔδειν αὐτόν ἀλλ’ … ἦλθον</span>, <strong>embora eu não o conhecesse, contudo vim</strong>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἶπον ὅτι οὐκ εἰμὶ ἐγὼ ὁ Χριστός, ἀλλ’ ὅτι\" data-meanings=\"eu disse: não sou o Cristo; antes, fui enviado adiante dele\">εἶπον [ὅτι] οὐκ εἰμὶ ἐγὼ ὁ Χριστός, ἀλλ’ ὅτι</span>, <strong>eu disse: “não sou o Cristo; antes, fui enviado adiante dele”</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">3.28</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὔτε οὗτος ἥμαρτεν οὔτε οἱ γονεῖς αὐτοῦ, ἀλλ’ ἵνα φανερωθῇ\" data-meanings=\"nem este pecou nem seus pais, mas [nasceu cego] para que se manifeste\">οὔτε οὗτος ἥμαρτεν οὔτε οἱ γονεῖς αὐτοῦ, ἀλλ’ ἵνα φανερωθῇ</span>, <strong>nem este homem pecou, nem seus pais, mas (nasceu cego) para que … fosse manifestado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">9.3</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Quando se comparam orações inteiras, pode indicar transição para algo diferente ou contrastante, o outro lado de uma questão: mas, contudo.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δεῖ γὰρ γενέσθαι, ἀλλ’ οὔπω ἐστὶν τὸ τέλος\" data-meanings=\"pois é necessário que aconteça, mas ainda não é o fim\">δεῖ γὰρ γενέσθαι, ἀλλ’ οὔπω ἐστὶν τὸ τέλος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.6</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.9</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κεκοίμηται· ἀλλὰ πορεύομαι ἵνα ἐξυπνίσω αὐτόν\" data-meanings=\"adormeceu; mas vou despertá-lo\">κεκοίμηται· ἀλλὰ πορεύομαι ἵνα ἐξυπνίσω αὐτόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.11</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">16.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">6.36</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.64\" target=\"_blank\" rel=\"noopener noreferrer\">64</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">8.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.18s.</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁμαρτία οὐκ ἐλλογεῖται … ἀλλὰ …\" data-meanings=\"o pecado não é imputado … contudo …\">ἁμαρτία οὐκ ἐλλογεῖται … ἀλλὰ …</span>, <strong>o pecado não é imputado; contudo …</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">5.13s.</a></p>\n<p class=\"entry-text\">Introduzindo uma objeção, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ἐρεῖ τις\" data-meanings=\"bem, alguém dirá\">ἀλλὰ ἐρεῖ τις</span> (Jos., <em>Bell.</em> 7, 363 e Just., <em>A I</em> 7, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ φήσει τις\" data-meanings=\"mas alguém dirá\">ἀλλὰ φήσει τις</span>), provavelmente coloquial, <strong>bem, alguém dirá</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.18</a> (diferentemente, D. Watson, NTS 39, 1993, 94–121). Retomando ou limitando uma afirmação precedente: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρένεγκε τὸ ποτήριον τοῦτο ἀπ’ ἐμοῦ· ἀλλ’ οὐ τί ἐγὼ θέλω\" data-meanings=\"afasta de mim este cálice; mas não o que eu quero\">παρένεγκε τὸ ποτήριον τοῦτο ἀπ’ ἐμοῦ· ἀλλ’ οὐ τί ἐγὼ θέλω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.36</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ οὐχ ὡς τὸ παράπτωμα, οὔτως καὶ τὸ χάρισμα\" data-meanings=\"mas o dom não é como a transgressão\">ἀλλ’ οὐχ ὡς τὸ παράπτωμα, οὔτως καὶ τὸ χάρισμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.15</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ οὐκ ἐχρησάμεθα τῇ ἐξουσίᾳ ταύτῃ\" data-meanings=\"mas não usamos desta autoridade\">ἀλλ’ οὐκ ἐχρησάμεθα τῇ ἐξουσίᾳ ταύτῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ἕκαστος ἴδιον ἔχει χάρισμα\" data-meanings=\"mas cada um tem seu próprio dom\">ἀλλὰ ἕκαστος ἴδιον ἔχει χάρισμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">7.7</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ καὶ περὶ τούτου δὲ εἴρηται\" data-meanings=\"mas também acerca disto se disse\">ἀλλὰ καὶ περὶ τούτου δὲ εἴρηται</span>, D 1:6.</p>\n<p class=\"entry-text\">Em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’, οὐ πάντες οἱ ἐξελθόντες …;\" data-meanings=\"mas não foram todos os que saíram …?\">ἀλλ’, οὐ πάντες οἱ ἐξελθόντες …;</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.16</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"mas; certamente\">ἀλλ’</span>, na opinião de alguns, teria surgido unicamente de uma compreensão equivocada do precedente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τίνες\" data-meanings=\"quais?\">τίνες</span> como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινές\" data-meanings=\"alguns\">τινές</span> por um copista antigo (B-D-F §448, 4); mas aqui <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"certamente; seguramente\">ἀλλά</span> pode transmitir forte asseveração: <strong>certamente</strong> (assim REB). Veja 3 abaixo.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Antes de orações independentes, indicando que o precedente deve ser considerado questão resolvida e formando transição para algo novo: mas</strong> (Just., <em>A I</em> 3; 10, 1). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ὁ ὄχλος οὗτος … ἐπάρατοί εἰσιν\" data-meanings=\"mas esta multidão … é maldita\">ἀλλὰ ὁ ὄχλος οὗτος … ἐπάρατοί εἰσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.49</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ ἐν τούτοις πᾶσιν ὑπερνικῶμεν\" data-meanings=\"mas em todas estas coisas somos mais que vencedores\">ἀλλ’ ἐν τούτοις πᾶσιν ὑπερνικῶμεν</span>, <strong>(não, de modo nenhum!) mas em todas estas coisas somos mais que vencedores</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.37</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ ὅτι ἃ θύουσιν, δαιμονίοις … θύουσιν\" data-meanings=\"mas o que sacrificam, sacrificam a demônios\">ἀλλ’ ὅτι ἃ θύουσιν, δαιμονίοις … θύουσιν</span>, <strong>(não!) mas aquilo que eles (os gentios) sacrificam, sacrificam a divindades inferiores</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10.20</a> (sua condição inferior é conotação de Paulo). Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.3</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.7s.</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ τί ἐξήλθατε ἰδεῖν;\" data-meanings=\"mas que saístes para ver?\">ἀλλὰ τί ἐξήλθατε ἰδεῖν;</span>, <strong>(não poderíeis ter querido ver aquilo;) mas que saístes para ver?</strong></p>\n<p class=\"entry-text\">Também deve ser explicado elipticamente o ascendente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ καί\" data-meanings=\"mas também\">ἀλλὰ καί</span>, <strong>(e não somente isto,) mas também</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">16.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">24.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.18</a> (Ath. 21, 4); negativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ οὐδέ\" data-meanings=\"mas nem sequer\">ἀλλ’ οὐδέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">4.3</a> (Ar. 9:1); reforçado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά γε καί\" data-meanings=\"sim, de fato; além disso\">ἀλλά γε καί</span>, <strong>de fato</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.21</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ μὲν οὖν γε καί\" data-meanings=\"sim, de fato; certamente\">ἀλλὰ μὲν οὖν γε καί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3.8</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.16</a> (veja 2 acima) pode muito bem ser traduzido, como NEB, <strong>todos aqueles, certamente, que Moisés havia conduzido para fora do Egito</strong> (compare Dio Crisóstomo 33, 36; 47, 3).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Para consideração alternativa/adicional fortemente marcada.</strong> <strong>a.</strong> Na apódose de períodos condicionais: <strong>contudo, certamente, pelo menos</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ καὶ πάντες σκανδαλισθήσονται, ἀλλ’ οὐκ ἐγώ\" data-meanings=\"ainda que todos se escandalizem, certamente eu não\">εἰ καὶ πάντες σκανδαλισθήσονται, ἀλλ’ οὐκ ἐγώ</span>, <strong>certamente eu não</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.29</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">5.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">11.6</a>. Reforçado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ καί\" data-meanings=\"certamente também\">ἀλλὰ καί</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ γὰρ σύμφυτοι γεγόναμεν … ἀλλὰ καὶ τῆς ἀναστάσεως ἐσόμεθα\" data-meanings=\"se fomos unidos … certamente também o seremos na ressurreição\">εἰ γὰρ σύμφυτοι γεγόναμεν …, ἀλλὰ καὶ τῆς ἀναστάσεως</span> (subentenda-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σύμφυτοι\" data-meanings=\"unidos; enxertados juntamente\">σύμφυτοι</span>) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐσόμεθα\" data-meanings=\"seremos\">ἐσόμεθα</span>, <strong>certamente seremos unidos a ele em sua ressurreição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.5</a>. Limitado por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γε\" data-meanings=\"ao menos; de fato\">γε</span> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ οὖν γε\" data-meanings=\"ao menos; contudo certamente\">ἀλλ’ οὖν γε</span>, Just., <em>D.</em> 76, 6; 93, 1): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἄλλοις οὐκ εἰμὶ ἀπόστολος, ἀλλά γε ὑμῖν εἰμι\" data-meanings=\"se para outros não sou apóstolo, pelo menos para vós sou\">εἰ ἄλλοις οὐκ εἰμὶ ἀπόστολος, ἀλλά γε ὑμῖν εἰμι</span>, <strong>pelo menos para vós eu sou</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.2</a> (compare Xenofonte, <em>Cyr.</em> 1, 3, 6; B-D-F §439, 2). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐὰν γὰρ μυρίους παιδαγωγοὺς ἔχητε ἐν Χριστῷ, ἀλλ’ οὐ πολλοὺς πατέρας\" data-meanings=\"ainda que tenhais dez mil preceptores em Cristo, certamente não muitos pais\">ἐὰν γὰρ μυρίους παιδαγωγοὺς ἔχητε ἐν Χριστῷ, ἀλλ’ οὐ πολλοὺς πατέρας</span>, <strong>certamente não muitos pais</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4.15</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Retoricamente ascendente: <strong>(não somente isto,) mas antes; até; sim, de fato</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πόσην κατειργάσατο ὑμῖν σπουδήν, ἀλλὰ ἀπολογίαν, ἀλλὰ ἀγανάκτησιν, ἀλλὰ φόβον, ἀλλὰ ἐπιπόθησιν, ἀλλὰ ζῆλον, ἀλλὰ ἐκδίκησιν\" data-meanings=\"quanta diligência produziu em vós, sim defesa, sim indignação, sim temor, sim saudade, sim zelo, sim punição\">πόσην κατειργάσατο ὑμῖν σπουδήν, ἀ. ἀπολογίαν, ἀ. ἀγανάκτησιν, ἀ. φόβον, ἀ. ἐπιπόθησιν, ἀ. ζῆλον, ἀ. ἐκδίκησιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7.11</a>. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.24</a>, veja 5 abaixo.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Com imperativo, para reforçar a ordem: agora, então</strong> (Arriano, <em>Anab.</em> 5, 26, 4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ παραμείνατε\" data-meanings=\"então permanecei!\">ἀλλὰ παραμείνατε</span> = “então permanecei!”; JosAs 13:9; ApcMos 3; SibOr 3, 624; 632; Jos., <em>Ant.</em> 4, 145): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ἐλθὼν ἐπίθες τὴν χεῖρά σου\" data-meanings=\"agora vem e põe tua mão sobre ela\">ἀλλὰ ἐλθὼν ἐπίθες τὴν χεῖρά σου</span>, <strong>agora vem e põe tua mão sobre ela</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.18</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ εἴ τι δύνῃ, βοήθησον\" data-meanings=\"agora, se podes algo, ajuda\">ἀλλ’ εἴ τι δύνῃ, βοήθησον</span>, <strong>agora ajuda-me, se podes (de algum modo)</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.22</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ὑπάγετε εἴπατε\" data-meanings=\"agora ide e dizei\">ἀλλὰ ὑπάγετε εἴπατε</span>, <strong>agora ide e dizei</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">16.7</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ἀναστὰς κατάβηθι\" data-meanings=\"agora levanta-te e desce\">ἀλλὰ ἀναστὰς κατάβηθι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.20</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλὰ ἀνάστηθι\" data-meanings=\"agora levanta-te\">ἀλλὰ ἀνάστηθι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">26.16</a> (JosAs 14:11).</p>\n<p class=\"entry-text\">No mesmo sentido com subjuntivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ … ἀπειλησώμεθα αὐτοῖς μηκέτι λαλεῖν\" data-meanings=\"agora advirtamo-los para que não falem mais\">ἀλλ’ … ἀπειλησώμεθα αὐτοῖς μηκέτι λαλεῖν</span>, <strong>agora advirtamo-los para que não falem mais</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.17</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ ὥσπερ ἐν παντὶ περισσεύετε … ἵνα καὶ ἐν ταύτῃ τῇ χάριτι περισσεύητε\" data-meanings=\"agora, assim como abundais em tudo … abundai também nesta graça\">ἀλλ’ ὥσπερ ἐν παντὶ περισσεύετε … ἵνα καὶ ἐν ταύτῃ τῇ χάριτι περισσεύητε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.7</a>. A menos que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.24</a> seja colocado em 4b, provavelmente deve ser entendido como elipse, expandível assim: <strong>então, assim como a igreja está sujeita a Cristo, as esposas também devem estar sujeitas a seus maridos</strong>. Contudo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"portanto; assim; consequentemente\">ἀλλά</span> também introduz uma inferência do que precede: <strong>assim, portanto, consequentemente</strong> (por exemplo, Aristófanes, <em>Ach.</em> 1189 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁδὶ δὲ καὐτός. Ἀλλ’ ἄνοιγε τὴν θύραν\" data-meanings=\"aqui está ele em pessoa. Então abre a porta\">ὁδὶ δὲ καὐτός. Ἀλλ’ ἄνοιγε τὴν θύραν</span> = “aqui está ele em pessoa. Então abre a porta”; <em>Birds</em> 1718; Herodas 7, 89; Artem. 4, 27 p. 219, 22; compare A. Moorehouse, ClQ 46, 1952, 100–104, sobre o <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"ἀλλά progressivo\">ἀλλά</span> “progressivo” como em <em>Od.</em> 3, 388). — M-M.</p>\n</section></article><article id=\"entry-allage-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλαγή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allagḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Ésquilo e outros; papiros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.18</a>; Just., <em>A I</em> 23, 2; Ath. 22, 3; Teófilo de Antioquia 1, 6 [p. 70, 1]; DELG I 64 s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>.) <strong>Mudança</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰς τῶν καιρῶν ἀλλαγὰς καταδιαιρεῖν\" data-meanings=\"distinguir as mudanças das estações\">τὰς τῶν καιρῶν ἀλλαγὰς καταδιαιρεῖν</span>, <strong>fazer distinção entre as mudanças das estações</strong>, Dg 4:5 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.18</a>; SibOr 2, 257).</p>\n</section></article><article id=\"entry-allasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλάσσω</h1><div class=\"entry-meta\"><span class=\"greek\">fut. ἀλλάξω; 1 aor. ἤλλαξα; 2 fut. pass. ἀλλαγήσομαι</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allássō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>.) Futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλάξω\" data-meanings=\"mudarei\">ἀλλάξω</span>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤλλαξα\" data-meanings=\"mudei; troquei\">ἤλλαξα</span>; 2º futuro passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλαγήσομαι\" data-meanings=\"serei mudado\">ἀλλαγήσομαι</span> (Ésquilo+; DELG I 64 s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Fazer algo tornar-se outro ou diferente: mudar, alterar.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν φωνήν μου\" data-meanings=\"meu tom; minha voz\">τὴν φωνήν μου</span>, <strong>mudar meu tom</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.20</a> (Artem. 2, 20, dos corvos, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πολλάκις ἀλλάσσειν τὴν φωνήν\" data-meanings=\"mudar frequentemente a voz\">πολλάκις ἀλλάσσειν τ. φωνήν</span>; TestJos 14:2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλάσσειν τὸν λόγον\" data-meanings=\"mudar a palavra; mudar o discurso\">ἀλλ. τὸν λόγον</span>; Just., <em>A I</em> 9, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ σχῆμα\" data-meanings=\"a forma; a aparência\">τὸ σχῆμα</span>). Da hiena, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν φύσιν\" data-meanings=\"a natureza\">τὴν φύσιν</span>, <strong>mudar sua natureza</strong>, B 10:7 (veja Windisch, Hdb. ad loc.). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰς χρόας\" data-meanings=\"as cores\">τὰς χρόας</span>, <strong>mudar as cores</strong> das pedras, Hs 9, 4, 5; 8. De Jesus no dia do juízo final, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλάξει τὸν ἥλιον καὶ τὴν σελήνην καὶ τοὺς ἀστέρας\" data-meanings=\"mudará o sol, a lua e as estrelas\">ἀλλάξει τὸν ἥλιον καὶ τὴν σελήνην καὶ τοὺς ἀστέρας</span>, <strong>mudará o sol, a lua e as estrelas</strong>, de modo que percam seu brilho, B 15:5. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἔθη\" data-meanings=\"os costumes\">τὰ ἔθη</span>, <strong>mudar os costumes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.14</a> (Diod S 1, 73, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰς τῶν θεῶν τιμὰς ἀλλάττειν\" data-meanings=\"mudar as honras dos deuses\">τὰς τῶν θεῶν τιμὰς ἀλλάττειν</span>).</p>\n<p class=\"entry-text\">Passivo (Dionísio, <em>Perieg.</em> [GGM II, p. 127, 392]; Herm. Wr. 1, 4; 13, 5; Jos., <em>Ant.</em> 2, 97 v.l.; SibOr 3, 638; 5, 273 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕως κόσμος ἀλλαγῇ\" data-meanings=\"até que o mundo seja mudado\">ἕως κόσμος ἀλλαγῇ</span>, dos últimos tempos; Ar. 5, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὕδωρ … ἀλλασσόμενον χρώμασι\" data-meanings=\"água … mudando de cores\">ὕδωρ … ἀλλασσόμενον χρώμασι</span>): da mudança na condição corporal dos cristãos no Último Dia, <strong>ser mudado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.51\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.51s.</a> (veja M. Dahl, <em>The Resurrection of the Body</em>, 1962, 103–105); da mudança efetuada por Cristo nos céus quando o mundo é destruído, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.12</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.101.27\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 101.27</a>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Trocar uma coisa por outra, trocar.</strong> (Ésquilo e outros; POxy 729, 43; BGU 1141, 41; 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 2.11</a>; Jos., <em>Ant.</em> 18, 237.) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤλλαξαν\" data-meanings=\"trocaram\">ἤλλαξαν</span> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλλάξαντο\" data-meanings=\"trocaram para si; forma média\">ἠλλάξαντο</span>, como no uso ático) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν δόξαν τοῦ ἀφθάρτου θεοῦ ἐν ὁμοιώματι εἰκόνος\" data-meanings=\"a glória do Deus incorruptível pela semelhança de uma imagem\">τὴν δόξαν τοῦ ἀφθάρτου θεοῦ ἐν ὁμοιώματι εἰκόνος</span>, <strong>trocaram a glória do Deus incorruptível por …</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.23</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλάσσω ἔν τινι\" data-meanings=\"trocar por algo\">ἀ. ἔν τινι</span> conforme <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.105.20\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 105.20</a>, onde traduz o hebraico <span dir=\"rtl\">הֵמִיר בְּ</span>; mas veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν\" data-meanings=\"em; por\">ἐν</span> 11). De pedras ruins em um edifício (compare PMich I, 41, 10), Hs 9, 5, 2. De trocar roupas (Apiano, <em>Bell. Civ.</em> 5, 122 §504 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἐσθῆτα ἤλλαξεν\" data-meanings=\"trocou a roupa\">τὴν ἐσθῆτα ἤλλαξεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.35.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 35.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Km 12.20</a>), Ox 840, 19 (ASyn. 150, 113). — B. 913. M-M. TW.</p>\n</section></article><article id=\"entry-allachothen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλαχόθεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦allachóthen⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de lugar (desde Antifonte 3, 4, 3; Apiano, <em>Liby.</em> 126 §604; Plutarco, <em>Fab.</em> 178 [6, 9], <em>Mor.</em> 1086d; 1129e; Jos., <em>Ant.</em> 2, 198; 4, 236; 18, 316; CPR 232, 28; POxy 237 V, 15 [186 d.C.]; 2410, 7 [120 d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 1.7</a>; Just., <em>D.</em> 92, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδαμόθεν … ἀλλαχόθεν\" data-meanings=\"de nenhum lugar … de outro lugar\">οὐδαμόθεν … ἀ.</span>), <strong>de outro lugar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβαίνειν\" data-meanings=\"subir; escalar\">ἀναβαίνειν</span>, <strong>subir por algum outro lugar</strong> (em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰσέρχεσθαι διὰ τῆς θύρας\" data-meanings=\"entrar pela porta\">εἰσέρχεσθαι διὰ τῆς θύρας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.1</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλο\" data-meanings=\"outro\">ἄλλο</span>. M-M.</p>\n</section></article><article id=\"entry-allachou-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλαχοῦ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦allachoû⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de lugar, <strong>em outro lugar</strong> (assim Sófocles, Xenofonte e outros; Just., <em>A I</em> 37, 3 em citação, e outros), também <strong>em outra direção</strong> (Epicteto 3, 23, 22; 3, 26, 4; Dio Crisóstomo 21 [38], 15; Polieno 1, 12; 1, 46; 4, 2, 21; SIG 888, 38 [238 d.C.]; Phryn. 43s. Lob.; TestAbr A 10 p. 87, 23; 25 [Stone p. 22]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλαχοῦ ἄγειν εἰς τὰς ἐχομένας κωμοπόλεις\" data-meanings=\"ir em outra direção para as vilas vizinhas\">ἀ. ἄγειν εἰς τὰς ἐχομένας κωμοπόλεις</span>, <strong>ir em outra direção para as vilas vizinhas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.38</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>. M-M.</p>\n</section></article><article id=\"entry-allegoreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλληγορέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦allēgoréō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγορεύω\" data-meanings=\"falar; discursar\">ἀγορεύω</span>, “falar”; Ateneu 2 p. 69c; Plutarco, <em>Mor.</em> 363d; Porfírio, <em>Vi. Pyth.</em> 12 Nauck; escólio a Píndaro, <em>O.</em> 10, 13a; Fílon, <em>Cher.</em> 25, <em>Somn.</em> 2, 31, <em>Vi. Cont.</em> 28; Jos., <em>Ant.</em> 1, 24; Did., <em>Gen.</em> 119, 2; Orígenes, <em>C. Cels.</em> 1, 17, 4 [com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τροπολογέω\" data-meanings=\"interpretar figuradamente\">τροπολογέω</span>]; Taciano 21, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς θεούς\" data-meanings=\"os deuses\">τοὺς θεούς</span>, “interpretar alegoricamente os deuses”.) <strong>Usar analogia ou semelhança para expressar algo, falar alegoricamente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅτινά ἐστιν ἀλληγορούμενα\" data-meanings=\"essas coisas são ditas alegoricamente\">ἅτινά ἐστιν ἀλληγορούμενα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.24</a>. (Compare Plutarco, <em>Mor.</em> 19f.)</p>\n<p class=\"entry-text\">F. Wehrli, <em>Zur Geschichte der allegorischen Deutung Homers</em>, diss. Basel 1928: esse tipo de interpretação era praticado em relação aos mitos pelo menos desde o século V a.C. Sobre interpretação alegórica entre gregos e judeus, compare Heráclito Estoico, <em>Allegoriae</em> = <em>Quaestiones Homericae</em> e, naturalmente, Fílon de Alexandria. — R. Hanson, <em>Allegory and Event</em>, 1959; N. Walter, <em>Der Thoraausleger Aristobulos</em>, em TU 86, 1964, 60s. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγορά\" data-meanings=\"assembleia; praça\">ἀγορά</span>. EDNT. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-hallelouia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁλληλουϊά</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hallēlouïá⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλληλουϊά\" data-meanings=\"formas variantes com ἀλ- ou -λούϊα\">ἀλ-</span> ou <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"-λούϊα\" data-meanings=\"forma variante\">-λούϊα</span>; empréstimo hebraico, literalmente <strong>louvai Yahweh</strong>, transliterado “hallelujah”.) Fórmula litúrgica do culto israelita (<span class=\"greek\">Ψαλμοί</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 13.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">3Mac 7.13</a>) e depois do culto cristão. Usada como tal em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμήν\" data-meanings=\"amém\">ἀμήν</span> (compare o hebraico de Sl 106.48; OdeSol 11:24; PGM 7, 271; um amuleto cristão, PBerol 6096, em Wilcken, APF 1, 1901, 430; E. Schaefer em PIand I p. 29), v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">4</a>. — H. Engberding, RAC I 293–299. — M-M. TW.</p>\n</section></article><article id=\"entry-allelon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλήλων</h1><div class=\"entry-meta\"><span class=\"greek\">gen.; dat. ἀλλήλοις; acc. ἀλλήλους</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allḗlōn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Genitivo do pronome recíproco; dativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλοις\" data-meanings=\"uns aos outros; uns para os outros\">ἀλλήλοις</span>; acusativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλους\" data-meanings=\"uns aos outros\">ἀλλήλους</span> (Homero+; Schwyzer I 446, n. 8): <strong>uns aos outros, um ao outro, mutuamente</strong>.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλων μέλη\" data-meanings=\"membros uns dos outros\">ἀλλήλων μέλη</span>, <strong>membros uns dos outros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.25</a>; 1 Cl 46:7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλων τὰ βάρη\" data-meanings=\"os fardos uns dos outros\">ἀ. τὰ βάρη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6.2</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταλαλεῖν ἀλλήλων\" data-meanings=\"falar mal uns dos outros\">καταλαλεῖν ἀ.</span>, <strong>falar mal uns dos outros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνέχεσθαι ἀλλήλων\" data-meanings=\"suportar uns aos outros\">ἀνέχεσθαι ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπ’ ἀλλήλων\" data-meanings=\"uns dos outros\">ἀπ’ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.39</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατ’ ἀλλήλων\" data-meanings=\"uns contra os outros\">κατ’ ἀ.</span> (Apiano, <em>Bell. Civ.</em> 5, 24 §95), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετ’ ἀλλήλων\" data-meanings=\"uns com os outros\">μετ’ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.56\" target=\"_blank\" rel=\"noopener noreferrer\">11.56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">16.19</a>; ITr 12:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μεταξὺ ἀλλήλων\" data-meanings=\"entre si\">μεταξὺ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρὰ ἀλλήλων\" data-meanings=\"uns dos outros\">παρὰ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.44</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπὲρ ἀλλήλων\" data-meanings=\"uns pelos outros\">ὑπὲρ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπ’ ἀλλήλων\" data-meanings=\"uns pelos outros\">ὑπ’ ἀ.</span> (Apiano, <em>Bell. Civ.</em> 5, 22 §89), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.15</a>.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλοις ἀντίκειται\" data-meanings=\"opõem-se um ao outro\">ἀλλήλοις ἀντίκειται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.17</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐγκαλεῖν ἀλλήλοις\" data-meanings=\"acusar uns aos outros\">ἐγκαλεῖν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.38</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀλλήλοις\" data-meanings=\"entre si\">ἐν ἀ.</span> (Jos., <em>Bell.</em> 2, 127, <em>Ant.</em> 9, 240; Just., <em>D.</em> 101, 3): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰρηνεύειν\" data-meanings=\"viver em paz\">εἰρηνεύειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.50</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.5</a>.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλους\" data-meanings=\"uns aos outros\">ἀλλήλους</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπᾶν ἀλλήλους\" data-meanings=\"amar uns aos outros\">ἀγαπᾶν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 5</a>; 2 Cl 9:6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παραδιδόναι ἀλλήλους\" data-meanings=\"entregar uns aos outros\">παραδιδόναι ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.10</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρὸς ἀλλήλους\" data-meanings=\"uns para com os outros\">πρὸς ἀ.</span> (Élio Aristides 46 p. 404 D.; En 6:2; Jos., <em>Ant.</em> 2, 108; Just., <em>A I</em> 61, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">8.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἀλλήλους\" data-meanings=\"uns para os outros\">εἰς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.10</a> (compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑαυτούς\" data-meanings=\"a vós mesmos; uns aos outros\">ἑαυτούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.8</a>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>.</p>\n</section></article><article id=\"entry-allogenes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλογενής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allogenḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(OGI 598 [séc. I d.C.], a famosa inscrição do templo de Jerusalém, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μηδένα ἀλλογενῆ εἰσπορεύεσθαι\" data-meanings=\"nenhum estrangeiro deve entrar\">μηδένα ἀλλογενῆ εἰσπορεύεσθαι</span>; veja Schürer II, 285 n. 57; Sb 6235, 6; LXX; PsSol 17:28; JosAs 4:12; Fílon; Jos., <em>Bell.</em> 2, 417; Just.) <strong>Estrangeiro</strong>, do samaritano agradecido: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ μὴ ὁ ἀλλογενὴς οὗτος\" data-meanings=\"exceto este estrangeiro\">εἰ μὴ ὁ ἀ. οὗτος</span>, <strong>exceto este estrangeiro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.18</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-alloioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλοιόω</h1><div class=\"entry-meta\"><span class=\"greek\">fut. 3 sg. ἀλλοιώσει; 1 aor. ἠλλοίωσα; pass. fut. ἀλλοιωθήσομαι; aor. ἠλλοιώθην; perf. ἠλλοίωμαι</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alloióō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sing. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοιώσει\" data-meanings=\"mudará\">ἀλλοιώσει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 12.18</a>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλλοίωσα\" data-meanings=\"mudei\">ἠλλοίωσα</span>. Passivo: futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοιωθήσομαι\" data-meanings=\"serei mudado\">ἀλλοιωθήσομαι</span>, LXX; aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλλοιώθην\" data-meanings=\"fui mudado\">ἠλλοιώθην</span>; perfeito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλλοίωμαι\" data-meanings=\"fui mudado; estou mudado\">ἠλλοίωμαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MAL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ml 3.6</a> (de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλοιος\" data-meanings=\"diferente\">ἄλλοιος</span>; pré-socráticos e outros; PEnteux 51, 6 [séc. III a.C.]; En; TestSol; TestJob; Test12Patr; Ar. 4, 1).</p>\n<p class=\"entry-text\"><strong>Fazer tornar-se diferente, mudar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ῥηθέν\" data-meanings=\"a palavra dita\">τὸ ῥηθέν</span>, <strong>a palavra</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 2.23</a>), de modo que se torne nula e sem efeito, 1 Cl 6:3. Da terra: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μηδὲ ἀλλοιοῦσά τι τῶν δεδογματισμένων ὑπ’ αὐτοῦ\" data-meanings=\"sem mudar nada daquilo que foi ordenado por ele\">μηδὲ ἀλλοιοῦσά τι τῶν δεδογματισμένων ὑπ’ αὐτοῦ</span>, <strong>sem mudar nenhuma das coisas que ele ordenou</strong>, 1 Cl 20:4 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 2.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">6.9</a>, ambos LXX e Teod.; En 2:1; 104:11).</p>\n<p class=\"entry-text\">Passivo, <strong>ser mudado</strong> (Tucídides 2, 59, 1; Antig. Car. 25, 164; Políbio 8, 27, 2; Dio Crisóstomo 35 [52], 13; En 2:2; Ar.; Just.; Ath. 22, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.29</a> D. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλλοιώθη ἡ ἰδέα αὐτοῦ\" data-meanings=\"sua aparência foi mudada\">ἠλλοιώθη ἡ ἰδέα αὐτοῦ</span>, Hv 5:4. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ μορφὴ αὐτοῦ ἠλλοιώθη\" data-meanings=\"sua forma foi mudada\">ἡ μορφὴ αὐτοῦ ἠλλοιώθη</span>, Hm 12, 4, 1 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 5.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">7.28</a>, ambos Teod.). — Hs 8, 5, 1. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>. TW.</p>\n</section></article>"};
